import React, { useState } from "react";
import HoneyComb from "../Assets/honeycomb.png";
import HoneyAmla from "../Assets/honeyamla.png";
import HoneyGarlic from "../Assets/honeygarlic.png";
import OriginalHoney from "../Assets/originalhoney.jpeg";
import "../App.css";

const products = [
  {
    id: 1,
    name_en: "Pure Forest Honey",
    name_ta: "தூய காட்டு தேன்",
    price: "₹450",
    image: OriginalHoney,
  },
  {
    id: 2,
    name_en: "Honey Comb",
    name_ta: "தேன் அடை",
    price: "₹380",
    image: HoneyComb,
  },
  {
    id: 3,
    name_en: "Honey with Amla",
    name_ta: "தேன் நெல்லிக்காய்",
    price: "₹520",
    image: HoneyAmla,
  },
  {
    id: 4,
    name_en: "Honey with Garlic",
    name_ta: "தேன் பூண்டு",
    price: "₹520",
    image: HoneyGarlic,
  },
];

function Home() {
  const [language, setLanguage] = useState("en");

  return (
    <div>
      {/* Navbar */}
      <nav
        className="navbar navbar-expand-lg px-4 sticky-top"
        style={{ backgroundColor: "#4e342e" }}
      >
        <a className="navbar-brand fw-bold text-white" href="#">
          O.I.HONEY WORLD
        </a>

        <div className="ms-auto">
          <a className="nav-link d-inline text-white me-3" href="#products">
            {language === "en" ? "Products" : "பொருட்கள்"}
          </a>
          <a className="nav-link d-inline text-white" href="#contact">
            {language === "en" ? "Contact" : "தொடர்பு"}
          </a>
        </div>
      </nav>

      {/* Language Toggle */}
      <div className="text-end px-4 py-2" style={{ backgroundColor: "#fff8e1" }}>
        <button
          className="btn btn-sm me-2 toggle-btn"
          onClick={() => setLanguage("en")}
        >
          English
        </button>

        <button
          className="btn btn-sm toggle-btn"
          onClick={() => setLanguage("ta")}
        >
          தமிழ்
        </button>
      </div>

      {/* Top Section */}
      <section className="top-section text-center py-5">
        <h1 className="fw-bold mb-3 title-animate">
          {language === "en"
            ? "100% Natural & Pure Honey 🍯"
            : "100% இயற்கை மற்றும் தூய தேன் 🍯"}
        </h1>

        <p className="lead subtitle-animate">
          {language === "en"
            ? "Fresh from the farm. No additives. No chemicals."
            : "பண்ணையிலிருந்து நேரடியாக. சேர்க்கைகள் இல்லை. ரசாயனங்கள் இல்லை."}
        </p>
      </section>

      {/* Products */}
      <section id="products" className="container py-5 product-section">
        <h2 className="text-center mb-5 fw-bold section-title">
          {language === "en" ? "Our Products" : "எங்கள் பொருட்கள்"}
        </h2>

        <div className="row">
          {products.map((product) => (
            <div key={product.id} className="col-md-3 mb-4">
              <div className="card product-card h-100">
                <img
                  src={product.image}
                  alt={
                    language === "en"
                      ? product.name_en
                      : product.name_ta
                  }
                  className="card-img-top"
                />

                <div className="card-body text-center">
                  <h5 className="fw-bold">
                    {language === "en"
                      ? product.name_en
                      : product.name_ta}
                  </h5>

                  <p className="price">{product.price}</p>

                  <button className="btn buy-btn">
                    {language === "en"
                      ? "Buy Now"
                      : "இப்போது வாங்க"}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Contact */}
      <section id="contact" className="text-center py-5 contact-section">
        <h2 className="fw-bold">
          {language === "en"
            ? "Contact Us"
            : "எங்களை தொடர்பு கொள்ள"}
        </h2>

        <p>
          📞 {language === "en" ? "Call Us:" : "தொலைபேசி:"} +91 97151 23277
        </p>

        <p>
          📍{" "}
          {language === "en"
            ? "1/14, Sivankudiyetru, Padukapathu, Thoothukudi, Tamil Nadu - 628703"
            : "1/14, சிவன்குடியேர்று, படுகாப்பத்து, தூத்துக்குடி, தமிழ்நாடு - 628703"}
        </p>
      </section>

      {/* Footer */}
      <footer className="text-center py-3 footer-section">
        <strong>© 2026 O.I.HONEY WORLD</strong>
      </footer>
    </div>
  );
}

export default Home;
